  // Path of the file relative to the collection directory
  string path = 2;
}

message FileLengthResponse {
  // Size of the file in bytes
  uint64 length = 1;
}

message ReadBytesRequest {
  // Name of the collection
  string collection_name = 1;
  // Path of the file relative to the collection directory
  string path = 2;
  // Offset in bytes to start reading from
  uint64 byte_offset = 3;
  // Number of bytes to read
  uint64 length = 4;
}

message ReadBytesResponse {
  // The requested bytes
  bytes data = 1;
}

message ReadBytesStreamRequest {
  // Name of the collection
  string collection_name = 1;
  // Path of the file relative to the collection directory
  string path = 2;
  // Offset in bytes to start reading from
  uint64 byte_offset = 3;
  // Number of bytes to read
  uint64 length = 4;
}

message ReadBytesStreamResponse {
  // A chunk of the requested bytes
  bytes data = 1;
}

message ReadWholeRequest {
  // Name of the collection
  string collection_name = 1;
  // Path of the file relative to the collection directory
  string path = 2;
}

message ReadWholeResponse {
  // The complete contents of the file
  bytes data = 1;
}

message ReadBatchRange {
  // Offset in bytes to start reading from
