/// Maximum number of bytes carried in a single [`ReadBytesStreamResponse`] chunk.
///
/// Reads larger than this value are split into chunks of exactly
/// `STREAM_CHUNK_SIZE` bytes, with a final chunk carrying the remainder.
pub const STREAM_CHUNK_SIZE: u64 = 2 * 1024 * 1024;

/// Abstraction over an opened storage file, allowing the service to be generic
/// over the concrete file backend (memory-mapped files in production).
pub trait StorageFile: Sized + Send + Sync + 'static {
    /// Open the file at the given (already validated) absolute path.
    fn open(path: &Path) -> io::Result<Self>;

    /// Length of the file in bytes.
    fn len(&self) -> u64;

    /// Read `length` bytes starting at `offset`.
    ///
    /// The caller guarantees that `offset + length` does not exceed [`Self::len`].
    fn read_range(&self, offset: u64, length: u64) -> io::Result<Vec<u8>>;
}

/// Memory-mapped file backend used in production.
pub struct MmapFile {
    /// The memory map, `None` for empty (zero-length) files which cannot be mapped.
    mmap: Option<memmap2::Mmap>,
    len: u64,
}

impl StorageFile for MmapFile {
    fn open(path: &Path) -> io::Result<Self> {
        let file = File::open(path)?;
        let len = file.metadata()?.len();
        // Memory maps must have a non-zero length, so skip mapping empty files.
        let mmap = if len == 0 {
            None
        } else {
            // SAFETY: the file is opened read-only and used only for reading.
            Some(unsafe { memmap2::Mmap::map(&file)? })
        };
        Ok(Self { mmap, len })
    }

    fn len(&self) -> u64 {
        self.len
    }

    fn read_range(&self, offset: u64, length: u64) -> io::Result<Vec<u8>> {
        if length == 0 {
            return Ok(Vec::new());
        }
        let data = self.mmap.as_deref().unwrap_or(&[]);
        let start = offset as usize;
        let end = start + length as usize;
        Ok(data[start..end].to_vec())
    }
}

/// gRPC service implementation for reading collection storage files.
pub struct StorageReadService<F = MmapFile> {
    dispatcher: Arc<Dispatcher>,
    _file: PhantomData<F>,
}

impl StorageReadService<MmapFile> {
    /// Construct a new [`StorageReadService`] backed by memory-mapped files.
    pub fn new(dispatcher: Arc<Dispatcher>) -> StorageReadService<MmapFile> {
        StorageReadService {
            dispatcher,
            _file: PhantomData,
        }
    }
}

/// Validate a relative path argument before it touches the filesystem.
///
/// Rejects `..` components, `.`/`./`-prefixed paths, and absolute paths.
fn validate_relative_path(path: &str) -> Result<(), Status> {
    if path == "." || path.starts_with("./") {
        return Err(Status::invalid_argument(format!(
            "Invalid path component: {path:?}"
        )));
    }

    for component in Path::new(path).components() {
        match component {
            Component::ParentDir => {
                return Err(Status::invalid_argument(
                    "Invalid path component: '..' is not allowed",
                ));
            }
            Component::CurDir => {
                return Err(Status::invalid_argument(
                    "Invalid path component: '.' is not allowed",
                ));
            }
            Component::RootDir | Component::Prefix(_) => {
                return Err(Status::invalid_argument(
                    "Invalid path: absolute paths are not allowed",
                ));
            }
            Component::Normal(_) => {}
        }
    }

    Ok(())
}

/// Check that `offset + length` stays within the file `len`, returning
/// [`tonic::Code::OutOfRange`] otherwise.
fn check_range(len: u64, offset: u64, length: u64) -> Result<(), Status> {
    let end = offset
        .checked_add(length)
        .ok_or_else(|| Status::out_of_range("Requested range overflows"))?;
    if offset > len || end > len {
        return Err(Status::out_of_range(format!(
            "Requested range [{offset}, {end}) exceeds file length {len}"
        )));
    }
    Ok(())
}

/// Canonicalize `target` and ensure it stays within `root`.
///
/// Returns `Ok(Some(real_path))` when the target exists and is contained,
/// `Ok(None)` when it does not exist, and an error when it escapes `root`.
#[cfg(unix)]
fn resolve_within(root: &Path, target: &Path) -> Result<Option<PathBuf>, Status> {
    match std::fs::canonicalize(target) {
        Ok(real) => {
            if real.starts_with(root) {
                Ok(Some(real))
            } else {
                Err(Status::permission_denied(
                    "Path resolves outside of the allowed directory",
                ))
            }
        }
        Err(err) if err.kind() == io::ErrorKind::NotFound => Ok(None),
        Err(err) => Err(Status::internal(format!("Failed to resolve path: {err}"))),
    }
}

#[cfg(not(unix))]
fn resolve_within(_root: &Path, target: &Path) -> Result<Option<PathBuf>, Status> {
    if target.exists() {
        Ok(Some(target.to_path_buf()))
    } else {
        Ok(None)
    }
}

/// Recursively collect regular files under `dir`, expressed relative to `base`.
fn collect_files(dir: &Path, base: &Path, out: &mut Vec<String>) -> io::Result<()> {
    for entry in std::fs::read_dir(dir)? {
        let entry = entry?;
        let file_type = entry.file_type()?;
        let path = entry.path();
        if file_type.is_dir() {
            collect_files(&path, base, out)?;
        } else if file_type.is_file() {
            if let Ok(relative) = path.strip_prefix(base) {
                out.push(relative.to_string_lossy().replace('\\', "/"));
            }
        }
        // Symlinks (neither dir nor file) are deliberately skipped.
    }
    Ok(())
}

