    Auth::new(access, None, None, AuthType::None, None)
}

#[tokio::test]
async fn test_file_exists_and_length() {
    let (svc, storage) = make_service();
    let dir = coll_dir(&storage, "c1");
    std::fs::write(dir.join("a.bin"), b"hello world").unwrap();

    let resp = svc
        .file_exists(Request::new(FileExistsRequest {
            collection_name: "c1".into(),
            path: "a.bin".into(),
        }))
        .await
        .unwrap();
    assert!(resp.into_inner().exists);

    let resp = svc
        .file_exists(Request::new(FileExistsRequest {
            collection_name: "c1".into(),
            path: "missing.bin".into(),
        }))
        .await
        .unwrap();
    assert!(!resp.into_inner().exists);

    let len = svc
        .file_length(Request::new(FileLengthRequest {
            collection_name: "c1".into(),
            path: "a.bin".into(),
        }))
        .await
        .unwrap();
    assert_eq!(len.into_inner().length, 11);

    // Missing file -> NotFound
    let err = svc
        .file_length(Request::new(FileLengthRequest {
            collection_name: "c1".into(),
            path: "nope.bin".into(),
        }))
        .await
        .unwrap_err();
    assert_eq!(err.code(), Code::NotFound);

    // Missing collection -> NotFound
    let err = svc
        .file_length(Request::new(FileLengthRequest {
            collection_name: "ghost".into(),
            path: "a.bin".into(),
        }))
        .await
        .unwrap_err();
    assert_eq!(err.code(), Code::NotFound);
}

